1	// Signs the persistent QA user in through the local /login page and saves e2e/.auth.json
2	// for the authenticated Playwright specs. The first run creates the user and stores its
3	// login as E2E_USER_EMAIL / E2E_USER_PASSWORD in the git-ignored .env.
4	// Run with the app on http://localhost:3000 (or E2E_BASE_URL):  node --env-file=.env scripts/e2e-auth.mjs
5	// Empty its workspace (specs expect one):      node --env-file=.env scripts/e2e-auth.mjs --reset
6	import { randomBytes } from "node:crypto";
7	import { appendFileSync } from "node:fs";
8	import { createClient } from "@supabase/supabase-js";
9	import { chromium } from "@playwright/test";
10	import postgres from "postgres";
11	
12	const statePath = "e2e/.auth.json";
13	let email = process.env.E2E_USER_EMAIL, password = process.env.E2E_USER_PASSWORD;
14	
15	if (process.argv.includes("--reset")) {
16	  if (!email) throw new Error("No E2E_USER_EMAIL in .env; run without --reset first");
17	  const db = postgres(process.env.SUPABASE_DB_URL, { max: 1, onnotice: () => {} });
18	  await db.begin(async tx => {
19	    const [user] = await tx`select id, raw_user_meta_data->>'qa_test' as qa from auth.users where email=${email}`;
20	    if (user?.qa !== "e2e-auth") throw new Error("Refusing to reset a user not created by this script");
21	    const workspaces = (await tx`select id from public.workspaces where owner_id=${user.id}`).map(row => row.id);
22	    // Audit tables reference each other, so skip FK triggers for this one owned sweep.
23	    // ponytail: column-name sweep; extend the list if a new owner column appears.
24	    await tx`set local session_replication_role = replica`;
25	    const columns = await tx`select table_name, column_name from information_schema.columns join information_schema.tables using (table_schema, table_name)
26	      where table_schema='public' and table_type='BASE TABLE' and table_name <> 'workspaces'
27	      and column_name in ('workspace_id','actor_id','user_id','created_by')`;
28	    for (const { table_name, column_name } of columns)
29	      await tx.unsafe(`delete from public."${table_name}" where "${column_name}"::text = any($1::text[])`, [[user.id, ...workspaces]]);
30	    // Same starting categories a new signup gets from seed_default_categories().
31	    await tx`insert into public.categories(workspace_id,name) select w,n from unnest(${workspaces}::uuid[]) w cross join unnest(public.default_category_names()) n`;
32	  });
33	  await db.end();
34	  console.log("Emptied the QA user's workspace");
35	  process.exit(0);
36	}
37	
38	if (!email) {
39	  email = `qa-${Date.now()}@example.test`;
40	  password = randomBytes(24).toString("base64url");
41	  const admin = createClient(process.env.NEXT_PUBLIC_SUPABASE_URL, process.env.SUPABASE_SERVICE_ROLE_KEY, { auth: { persistSession: false } });
42	  const { error } = await admin.auth.admin.createUser({ email, password, email_confirm: true, user_metadata: { qa_test: "e2e-auth" } });
43	  if (error) throw error;
44	  appendFileSync(".env", `\nE2E_USER_EMAIL=${email}\nE2E_USER_PASSWORD=${password}\n`);
45	}
46	
47	const browser = await chromium.launch();
48	try {
49	  const page = await browser.newPage({ baseURL: process.env.E2E_BASE_URL ?? "http://localhost:3000" });
50	  await page.goto("/login");
51	  await page.getByLabel("Email").fill(email);
52	  await page.getByLabel("Password").fill(password);
53	  await page.getByRole("button", { name: "Sign in", exact: true }).click();
54	  await page.waitForURL(url => !url.pathname.startsWith("/login"), { timeout: 60_000 });
55	  await page.context().storageState({ path: statePath });
56	  console.log(`Saved ${statePath} for ${email}`);
57	} finally {
58	  await browser.close();
59	}
