19	export default function LoginPage() {
20	  const router = useRouter();
21	  const [mode, setMode] = useState<Mode>("sign-in");
22	  const [email, setEmail] = useState("");
23	  const [password, setPassword] = useState("");
24	  const [message, setMessage] = useState<string | null>(null);
25	  const [pending, setPending] = useState(false);
26	  const submitting = useRef(false);
27	  const failedCallback = useSyncExternalStore(subscribeToCallback, callbackError, () => false);
28	
29	  async function submit(event: React.FormEvent<HTMLFormElement>) {
30	    event.preventDefault();
31	    if (submitting.current) return;
32	    submitting.current = true;
33	    setPending(true);
34	    setMessage("");
35	    try {
36	      const auth = createClient().auth;
37	      const callback = `${window.location.origin}/auth/callback`;
38	      if (mode === "magic-link") {
39	        const { error } = await auth.signInWithOtp({ email, options: { emailRedirectTo: callback } });
40	        setMessage(error?.message ?? "Check your email for the sign-in link.");
41	      } else if (mode === "forgot") {
42	        const { error } = await auth.resetPasswordForEmail(email, { redirectTo: `${callback}?next=/reset-password` });
43	        setMessage(error?.message ?? "Check your email for the password reset link.");
44	      } else {
45	        const { data, error } = mode === "sign-in"
46	          ? await auth.signInWithPassword({ email, password })
47	          : await auth.signUp({ email, password, options: { emailRedirectTo: callback } });
48	        if (error) setMessage(error.message);
