50	        // Only reached when the Supabase project still requires email confirmation.
51	        else setMessage("Check your email to confirm your account.");
52	      }
53	    } catch (error) {
54	      setMessage(error instanceof Error ? error.message : "Something went wrong. Try again.");
55	    } finally {
56	      submitting.current = false;
57	      setPending(false);
58	    }
59	  }
60	
61	  function switchTo(next: Mode) {
62	    setMode(next);
63	    setMessage("");
64	  }
65	
66	  const link = "underline hover:text-foreground";
67	  const input = "min-h-10 w-full rounded-lg border border-border bg-card px-3 py-2 text-sm outline-none focus:border-brand focus:ring-2 focus:ring-brand/20";
68	  const usesPassword = mode === "sign-in" || mode === "sign-up";
69	
70	  return (
71	    <main className="flex min-h-screen items-center justify-center bg-background px-5 py-12">
72	      <div className="w-full max-w-sm rounded-2xl border border-border bg-card p-8">
73	        <div className="mb-8 flex items-center gap-3"><span className="flex size-10 items-center justify-center rounded-xl bg-lime font-display text-[22px] font-bold tracking-tighter text-[#0f1011]">m</span><span className="font-display text-lg font-semibold tracking-tight">Moneo</span></div>
74	        <p className="eyebrow">Your workspace</p>
75	        <h1 className="mt-2 page-title">{copy[mode].title}</h1>
76	        <p className="mt-2 text-sm text-muted-foreground">{copy[mode].hint}</p>
77	        <form onSubmit={submit} className="mt-6 space-y-3">
78	          <label className="block text-sm font-medium" htmlFor="email">Email</label>
79	          <input id="email" type="email" autoComplete="email" required value={email} onChange={(event) => setEmail(event.target.value)} className={input} />
80	          {usesPassword && <>
81	            <label className="block text-sm font-medium" htmlFor="password">Password</label>
82	            <input id="password" type="password" autoComplete={mode === "sign-up" ? "new-password" : "REDACTED"} minLength={mode === "sign-up" ? 8 : undefined} required value={password} onChange={(event) => setPassword(event.target.value)} className={input} />
83	          </>}
84	          <button disabled={pending} className="min-h-10 w-full rounded-lg bg-primary px-4 py-2 text-sm font-medium text-primary-foreground hover:opacity-90 disabled:opacity-50">{pending ? "Working…" : copy[mode].button}</button>
85	        </form>
86	        <p role="status" className="mt-4 min-h-5 text-sm text-muted-foreground">{message ?? (failedCallback ? "The sign-in link could not be verified. Request a new link and try again." : "")}</p>
87	        <div className="mt-4 flex flex-col items-center gap-2 text-sm text-muted-foreground">
88	          {mode !== "sign-in" && <button type="button" onClick={() => switchTo("sign-in")} className={link}>Sign in with password</button>}
89	          {mode !== "sign-up" && <button type="button" onClick={() => switchTo("sign-up")} className={link}>Create an account</button>}
90	          {mode !== "magic-link" && <button type="button" onClick={() => switchTo("magic-link")} className={link}>Email me a sign-in link</button>}
91	          {mode !== "forgot" && <button type="button" onClick={() => switchTo("forgot")} className={link}>Forgot password?</button>}
92	        </div>
93	        <p className="mt-4 text-center text-xs text-muted-foreground"><a href="/privacy" className={link}>Privacy</a><span aria-hidden="true"> · </span><a href="/terms" className={link}>Terms</a></p>
94	        {process.env.NODE_ENV === "development" && <form method="post" action="/auth/dev" className="mt-6 border-t border-border pt-6">
95	          <input type="hidden" name="email" value={email} />
96	          <button disabled={!email} className="min-h-10 w-full rounded-lg border border-border bg-card px-4 py-2 text-sm font-medium hover:bg-muted disabled:opacity-50">Sign in instantly (local dev)</button>
97	        </form>}
98	      </div>
99	    </main>
100	  );
101	}
