109	  // Merge rules keep a delayed or reordered status response from regressing a newer state.
110	  function mergeHistory(updates: HistoryUpdate[], requestOrder: number) {
111	    setHistory((current) => {
112	      const byId = new Map(current.map((item) => [item.id, item]));
113	      for (const update of updates) {
114	        const previous = byId.get(update.id);
115	        const sameRun = previous && update.run_version === previous.run_version;
116	        const stage = (status: string) => ["pending", "queued", "running"].indexOf(status);
117	        const previousStage = previous ? stage(previous.status) : -1;
118	        const nextStage = stage(update.status);
119	        const regresses = previous && (previousStage < 0
120	          ? update.status !== previous.status && !(previous.status === "completed" && update.status === "undone")
121	          : nextStage >= 0 && nextStage < previousStage);
122	        if (previous && (update.run_version < previous.run_version || (sameRun &&
123	          (regresses || (update.status === previous.status && requestOrder < (historyApplied.current.get(update.id) ?? 0)))))) continue;
124	        if (!previous && !update.filename) continue;
125	        byId.set(update.id, { ...previous, ...update } as ImportStatus);
126	        historyApplied.current.set(update.id, Math.max(requestOrder, historyApplied.current.get(update.id) ?? 0));
127	      }
128	      return [...byId.values()].sort((a, b) => b.created_at.localeCompare(a.created_at)).slice(0, 30);
129	    });
