28	async function json<T>(input: string, init?: RequestInit): Promise<T> {
29	  const response = await fetch(input, { cache: "no-store", ...init });
30	  const body = await response.json().catch(() => ({}));
31	  if (!response.ok) throw new Error(body.error ?? "Request failed. Try again.");
32	  return body as T;
33	}
34	const seed = (initial: ChatWorkspaceInitial): Record<string, Entry> => initial.selected ? { [initial.selected.id]: { conversation: initial.selected, messages: initial.messages, cursor: initial.messagesCursor, running: initial.running } } : {};
35	const loaded = (data: Loaded): Entry => ({ conversation: data.selected, messages: data.messages, cursor: data.messagesCursor, running: data.running });
36	function omit<T>(record: Record<string, T>, key: string) { const next = { ...record }; delete next[key]; return next; }
37	const href = (id: string) => `/ai?conversation=${id}`;
38	const fetchEntry = (id: string) => json<Loaded>(`/api/conversations/${id}`);
