40	/** Client-side chat workspace: switching, paging, search, rename and delete never re-render the server page. */
41	export function ChatWorkspace({ initial, newConversationId, selectionKey, locale, timezone, scope }: { initial: ChatWorkspaceInitial; newConversationId: string; selectionKey: string; locale: string; timezone: string; scope: React.ReactNode }) {
42	  const [seen, setSeen] = useState(initial);
43	  const [threads, setThreads] = useState(initial.threads);
44	  const [threadsCursor, setThreadsCursor] = useState(initial.threadsCursor);
45	  const [entries, setEntries] = useState(() => seed(initial));
46	  // A server re-render (for example after the panel starts a chat) refreshes the cached view.
47	  if (seen !== initial) { setSeen(initial); setThreads(initial.threads); setThreadsCursor(initial.threadsCursor); setEntries(current => ({ ...current, ...seed(initial) })); }
48	  const [errors, setErrors] = useState<Record<string, string>>({});
49	  const [pending, setPending] = useState<Record<string, PendingExchange>>({});
50	  const [draftId, setDraftId] = useState(newConversationId);
51	  const [query, setQuery] = useState("");
52	  const [results, setResults] = useState<HistoryThread[] | null>(null);
53	  const [notice, setNotice] = useState("");
54	  const [editing, setEditing] = useState<string | null>(null);
55	  const [busy, setBusy] = useState(false);
56	  const [reviewOpen, setReviewOpen] = useState(false);
57	  const loading = useRef(new Set<string>());
58	  const menu = useRef<HTMLDetailsElement>(null);
59	  const end = useRef<HTMLDivElement>(null);
60	
61	  const params = useSearchParams();
62	  const param = params.get("conversation");
63	  // Overview's Call opens chat already calling; the flag is dropped once read, so a reload does not call again.
64	  const autoCall = params.get("call") === "1";
65	  const [calling, setCalling] = useState(autoCall);
66	  useEffect(() => {
67	    if (!autoCall) return;
68	    const url = new URL(window.location.href); url.searchParams.delete("call"); window.history.replaceState(null, "", url);
69	  }, [autoCall]);
70	  const selectedId = param === "new" ? null : param ?? initial.selected?.id ?? null;
71	  const activeId = selectedId ?? draftId;
72	  const entry = entries[activeId];
73	  const active = pending[activeId];
74	
75	  function load(id: string) {
76	    if (entries[id] || errors[id] || loading.current.has(id)) return;
77	    loading.current.add(id);
78	    json<Loaded>(`/api/conversations/${id}`)
79	      .then(data => { setEntries(current => current[id] ? current : { ...current, [id]: loaded(data) }); setErrors(current => omit(current, id)); })
80	      .catch(cause => setErrors(current => ({ ...current, [id]: cause.message })))
81	      .finally(() => loading.current.delete(id));
82	  }
83	  const latest = useRef({ selectedId, draftId });
84	  useEffect(() => { latest.current = { selectedId, draftId }; if (selectedId) load(selectedId); }); // load() skips cached and in-flight chats
85	  useEffect(() => { end.current?.scrollIntoView({ block: "end" }); }, [activeId, entry?.messages.length, active]);
86	  // A run that kept going while the user was away shows as working until its answer is saved.
87	  const resuming = entry?.running && !active ? activeId : null;
88	  usePolling(() => void json<Loaded>(`/api/conversations/${resuming}`)
89	    .then(data => { if (!data.running) setEntries(current => ({ ...current, [resuming!]: loaded(data) })); }).catch(() => {}), 3000, !!resuming);
