1	"use client";
2	
3	import { useState, type FormEvent } from "react";
4	import { useRouter } from "next/navigation";
5	import { formatInputAmount } from "@/lib/finance/format";
6	import { parseManualAmount } from "./input";
7	import { compileFilterQuery } from "./nl-filter";
8	import { calendarDate } from "@/lib/finance/calendar";
9	
10	type Named = { id: string; name: string };
11	export type FilterValues = Partial<Record<"q" | "from" | "to" | "account" | "category" | "merchant" | "status" | "kind" | "direction" | "tag" | "event" | "minAmount" | "maxAmount" | "sort" | "group", string>>;
12	
13	const control = "min-h-10 w-full rounded-[10px] border border-input bg-card px-3 py-2 text-[13px]";
14	
15	/**
16	 * Compact filter bar. Everything lives in the URL; amounts are typed as
17	 * decimals in the account (or display) currency and converted exactly to
18	 * minor units before they reach the URL.
19	 */
20	export function FilterBar({ values, accounts, categories, merchants, displayCurrency, timezone = "UTC" }: {
21	  values: FilterValues; accounts: (Named & { currency_code: string })[]; categories: Named[]; merchants: Named[]; displayCurrency: string; timezone?: string;
22	}) {
23	  const router = useRouter();
24	  const [account, setAccount] = useState(values.account ?? "");
25	  const [error, setError] = useState("");
26	  const currency = accounts.find(row => row.id === account)?.currency_code ?? displayCurrency;
27	  const decimal = (minor?: string) => minor === undefined ? "" : formatInputAmount(minor, currency);
28	  const [more, setMore] = useState(Boolean(values.minAmount || values.maxAmount || values.status || values.kind || values.direction || values.tag || values.event));
29	
30	  function submit(event: FormEvent<HTMLFormElement>) {
31	    event.preventDefault();
32	    const form = new FormData(event.currentTarget);
33	    const params = new URLSearchParams();
34	    try {
35	      for (const [key, raw] of form) {
36	        const value = String(raw).trim();
37	        if (!value) continue;
38	        params.set(key, key === "minAmount" || key === "maxAmount" ? parseManualAmount(value, currency).toString() : value);
39	      }
40	    } catch (cause) { setError(cause instanceof Error ? cause.message : "Check the amount"); return; }
41	    for (const key of ["sort", "group"] as const) if (values[key]) params.set(key, values[key]!);
42	    setError("");
43	    router.push(`/money/transactions${params.size ? `?${params}` : ""}`);
44	  }
45	
46	  function ask(event: FormEvent<HTMLFormElement>) {
47	    event.preventDefault();
48	    const text = String(new FormData(event.currentTarget).get("ask") ?? "").trim();
49	    if (!text) return;
50	    const { params } = compileFilterQuery(text, { today: calendarDate(new Date(), timezone), currency, accounts, categories, merchants });
51	    const query = new URLSearchParams(Object.entries(params).filter((entry): entry is [string, string] => Boolean(entry[1])));
52	    router.push(`/money/transactions${query.size ? `?${query}` : ""}`);
53	  }
54	
55	  return <div className="space-y-2">
56	  <form onSubmit={ask} role="search" aria-label="Describe transactions" className="flex gap-2">
57	    <input name="ask" maxLength={200} placeholder="Ask, e.g. coffee over 5 last month" aria-label="Describe what to find" className={`${control} flex-1`} />
58	    <button className="min-h-10 whitespace-nowrap rounded-[10px] border border-input px-3 text-[13px] hover:bg-muted">Find</button>
59	  </form>
60	  <form onSubmit={submit} role="search" aria-label="Filter transactions" className="space-y-2">
61	    <div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-4">
62	      <input id="ledger-search" name="q" defaultValue={values.q} placeholder="Search descriptions  ( / )" aria-label="Search descriptions" maxLength={200} className={control} />
63	      <input name="from" type="date" defaultValue={values.from} aria-label="From date" className={control} />
64	      <input name="to" type="date" defaultValue={values.to} aria-label="To date" className={control} />
65	      <select name="account" value={account} onChange={event => setAccount(event.target.value)} aria-label="Account" className={control}><option value="">All accounts</option>{accounts.map(row => <option key={row.id} value={row.id}>{row.name}</option>)}</select>
66	      <select name="category" defaultValue={values.category ?? ""} aria-label="Category" className={control}><option value="">All categories</option><option value="none">Uncategorized</option>{categories.map(row => <option key={row.id} value={row.id}>{row.name}</option>)}</select>
67	      <select name="merchant" defaultValue={values.merchant ?? ""} aria-label="Merchant" className={control}><option value="">All merchants</option><option value="none">Unknown</option>{merchants.map(row => <option key={row.id} value={row.id}>{row.name}</option>)}</select>
68	      <div className="flex gap-2 lg:col-span-2 lg:justify-end">
69	        <button type="button" aria-expanded={more} onClick={() => setMore(!more)} className="min-h-10 whitespace-nowrap rounded-[10px] border border-input px-3 text-[13px] hover:bg-muted">{more ? "Fewer" : "More"}</button>
70	        <button className="min-h-10 whitespace-nowrap rounded-[10px] bg-primary px-4 text-[13px] font-medium text-primary-foreground hover:opacity-90">Apply filters</button>
71	      </div>
72	    </div>
73	    <div hidden={!more} className="grid gap-2 sm:grid-cols-3 lg:grid-cols-7">
74	      <input key={`min-${currency}`} name="minAmount" defaultValue={decimal(values.minAmount)} placeholder={`Min amount (${currency})`} aria-label={`Minimum amount in ${currency}`} inputMode="decimal" className={control} />
75	      <input key={`max-${currency}`} name="maxAmount" defaultValue={decimal(values.maxAmount)} placeholder={`Max amount (${currency})`} aria-label={`Maximum amount in ${currency}`} inputMode="decimal" className={control} />
76	      <select name="direction" defaultValue={values.direction ?? ""} aria-label="Direction" className={control}><option value="">Money in and out</option><option value="income">Money in</option><option value="outflow">Money out</option></select>
77	      <select name="status" defaultValue={values.status ?? ""} aria-label="Status" className={control}><option value="">Any status</option><option value="posted">Posted</option><option value="pending">Pending</option></select>
78	      <select name="kind" defaultValue={values.kind ?? ""} aria-label="Type" className={control}><option value="">Any type</option><option value="ordinary">Regular</option><option value="transfer">Transfer</option><option value="refund">Refund</option></select>
79	      <input name="tag" defaultValue={values.tag} placeholder="Tag" aria-label="Filter by tag" maxLength={40} className={control} />
80	      <input name="event" defaultValue={values.event} placeholder="Trip / event group" aria-label="Filter by spending group" maxLength={120} className={control} />
81	    </div>
82	    {more && <p className="text-xs text-muted-foreground">Amounts are signed: -50 to -10 finds purchases between 10 and 50.</p>}
83	    {error && <p role="alert" className="text-sm text-danger">{error}</p>}
84	  </form>
85	  </div>;
86	}
