21	  try { context = await requireWorkspace(); } catch { redirect("/login"); }
22	  const { supabase, workspace } = context;
23	  const money = (amount: string | bigint, currency: string) => formatMoney(amount, currency, workspace.locale);
24	  const today = calendarDate(new Date(), workspace.timezone);
25	
26	  const [{ data: accounts, error: accountsError }, { data: scheduleData, error: schedulesError }, { data: categoryData }] = await Promise.all([
27	    supabase.from("accounts").select("id, name, currency_code, archived_at").eq("workspace_id", workspace.id).order("name"),
28	    supabase.from("financial_assumptions").select("id, name, category:categories(name), account_id, amount_minor::text, currency_code, cadence, starts_on, ends_on, schedule_anchor_on, source")
29	      .eq("workspace_id", workspace.id).eq("confirmed", true).eq("enabled", true).is("removed_at", null).in("cadence", recurringCadences).order("name").limit(500),
30	    supabase.from("categories").select("name").eq("workspace_id", workspace.id).order("name").limit(500),
31	  ]);
32	  const categories = (categoryData ?? []).map(row => row.name as string);
33	  const liveAccounts = (accounts ?? []).filter(account => !account.archived_at).map(account => ({ id: account.id as string, name: account.name as string, currencyCode: account.currency_code as string }));
34	  const names: Record<string, string> = Object.fromEntries((accounts ?? []).map(account => [account.id, account.name]));
35	
36	  // Same expansion as the forecast, so "next" here matches Plan. Account-less schedules still get a date.
37	  const schedules = ((scheduleData ?? []) as unknown as Schedule[]).map(item => {
38	    const dated = { ...item, account_id: item.account_id ?? "unassigned" };
39	    const upcoming = expandSchedule(dated, today, UPCOMING_DAYS);
40	    const amount = BigInt(item.amount_minor);
41	    return { ...item, amount, next: expandSchedule(dated, today, 400)[0]?.date ?? null, upcoming: amount * BigInt(upcoming.length), monthly: monthlyEquivalent(amount, item.cadence) };
