43	  const totals = new Map<string, { out: bigint; in: bigint; upcoming: bigint }>();
44	  for (const item of schedules) {
45	    if (!item.next) continue;
46	    const total = totals.get(item.currency_code) ?? { out: 0n, in: 0n, upcoming: 0n };
47	    if (item.monthly < 0n) total.out += item.monthly; else total.in += item.monthly;
