61	          triggerClassName="min-h-10 w-fit rounded-lg bg-primary px-4 text-sm font-medium text-primary-foreground hover:opacity-90"
62	          defaults={{ name: "", amount: "", direction: "out", cadence: "monthly", startsOn: today, category: "" }} />}
63	      </header>
64	      {accountsError && <p role="alert">Could not load accounts: {accountsError.message}</p>}
65	      <Suspense fallback={null}><RecurringReview supabase={supabase} workspace={workspace} prices /></Suspense>
66	
67	      <section aria-label="Bills and subscriptions" className="space-y-3">
68	        <div className="flex flex-wrap items-end justify-between gap-4">
69	          <h2 className="text-sm font-medium">Bills and subscriptions</h2>
70	          {totals.size > 0 && <dl className="flex flex-wrap gap-x-6 gap-y-1 text-right text-sm">{[...totals].map(([currency, total]) => <div key={currency} className="grid">
71	            <dt className="text-xs text-muted-foreground">Per month ({currency})</dt>
72	            <dd className="font-mono font-semibold tabular-nums">{money(total.out, currency)}{total.in > 0n && <span className="ml-2 text-success">+{money(total.in, currency)} in</span>}</dd>
73	            <dd className="text-xs text-muted-foreground">Next {UPCOMING_DAYS} days: {money(total.upcoming, currency)}</dd>
74	          </div>)}</dl>}
75	        </div>
76	        {schedulesError ? <p role="alert">Could not load confirmed schedules: {schedulesError.message}</p> : schedules.length ? <div className="overflow-x-auto rounded-xl border border-border bg-card">
77	          <table className="w-full min-w-[480px] text-left text-sm">
78	            <thead className="border-b border-border text-xs text-muted-foreground"><tr>
79	              <th className="px-4 py-2.5 font-medium">Name</th><th className="px-3 py-2.5 font-medium">Category</th><th className="px-3 py-2.5 font-medium">Cadence</th><th className="px-3 py-2.5 font-medium">Next</th>
80	              <th className="px-4 py-2.5 text-right font-medium">Amount</th>
81	            </tr></thead>
82	            <tbody className="divide-y divide-border">{schedules.map(item => <tr key={item.id} className={item.next ? "" : "text-muted-foreground"}>
83	              <td className="px-4 py-2.5"><ScheduleDialog title={`Edit ${item.name}`} trigger={item.name} triggerClassName="text-left font-medium hover:underline" submitLabel="Save"
84	                action={updateSchedule} remove={deleteSchedule} hidden={{ assumptionId: item.id }} categories={categories}
85	                defaults={{ name: item.name, amount: formatInputAmount(item.amount < 0n ? -item.amount : item.amount, item.currency_code), direction: item.amount < 0n ? "out" : "in",
86	                  cadence: item.cadence, startsOn: item.next ?? item.starts_on, category: item.category?.name ?? "", currencyCode: item.currency_code }} />
87	                <span className="ml-2 text-xs text-muted-foreground">{item.account_id ? names[item.account_id] ?? "Unknown account" : "No account"}</span></td>
88	              <td className="px-3 py-2.5 text-muted-foreground">{item.category?.name ?? "—"}</td>
89	              <td className="px-3 py-2.5 capitalize">{item.cadence}</td>
90	              <td className="whitespace-nowrap px-3 py-2.5 font-mono">{item.next ?? "Ended"}</td>
91	              <td className={`whitespace-nowrap px-4 py-2.5 text-right font-mono tabular-nums ${item.amount > 0n ? "text-success" : ""}`}>{money(item.amount, item.currency_code)}</td>
92	            </tr>)}</tbody>
93	          </table>
94	        </div> : <p className="rounded-xl border border-dashed border-border p-5 text-center text-sm text-muted-foreground">No confirmed schedules yet. Confirm a detected pattern below or add one with Add recurring.</p>}
95	        <p className="text-xs text-muted-foreground">Click a name to change its amount, date or category, or to remove it. Pause or end a schedule in <Link href="/plan" className="underline">Plan</Link>. Monthly totals are per currency (52 weeks a year).</p>
96	      </section>
97	
98	      <Suspense fallback={<p className="rounded-xl border border-border bg-card p-5 text-sm text-muted-foreground">Looking for recurring patterns in your history…</p>}>
99	        <DetectedPatterns supabase={supabase} workspace={workspace} names={names} today={today} categories={categories} />
100	      </Suspense>
101	      <Suspense fallback={null}>
102	        <OccurrenceReview supabase={supabase} workspace={workspace} accountNames={names} />
103	      </Suspense>
104	    </main>
105	  );
106	}
