8	type Action = (state: ActionState, form: FormData) => Promise<ActionState>;
9	const inputClass = "min-h-10 w-full rounded-lg border border-border bg-background px-3 py-2 text-sm";
10	const cadenceWords: Record<string, string> = { weekly: "Every week", biweekly: "Every two weeks", monthly: "Every month", quarterly: "Every quarter", yearly: "Every year" };
11	
12	function Hidden({ values }: { values: Record<string, string> }) {
13	  return <>{Object.entries(values).map(([name, value]) => <input key={name} type="hidden" name={name} value={value} />)}</>;
14	}
