16	/** A plain form whose failure is shown next to it instead of crashing the page. */
17	export function ActionForm({ action, hidden = {}, className, children }: { action: Action; hidden?: Record<string, string>; className?: string; children: React.ReactNode }) {
18	  const [state, submit, pending] = useActionState<ActionState, FormData>(action, {});
19	  return <form action={submit} className={className}>
20	    <Hidden values={hidden} />
21	    <fieldset disabled={pending} className="contents">{children}</fieldset>
22	    {state.error && <p role="alert" className="basis-full text-xs text-danger">{state.error}</p>}
23	  </form>;
24	}
