26	export type ScheduleDefaults = { name: string; amount: string; direction: "out" | "in"; cadence: string; startsOn: string; category: string; currencyCode?: string };
27	
28	/** Opens a dialog to confirm, edit or add a recurring payment: how much, which way, how often, the next date and a category. */
29	export function ScheduleDialog({ title, trigger, triggerClassName, action, remove, hidden = {}, defaults, accounts, categories, submitLabel, onDone }: {
30	  title: string; trigger: React.ReactNode; triggerClassName?: string; action: Action; remove?: Action; hidden?: Record<string, string>; defaults: ScheduleDefaults;
31	  accounts?: { id: string; name: string; currencyCode: string }[]; categories: string[]; submitLabel: string; onDone?: () => void;
32	}) {
33	  // When it was opened; a submission that succeeds after that closes it. The action refreshes the page.
34	  const [openedAt, setOpenedAt] = useState<number | null>(null);
35	  const [state, submit, pending] = useActionState<ActionState, FormData>(action, {});
36	  const [removed, removeSubmit, removing] = useActionState<ActionState, FormData>(remove ?? (async () => ({})), {});
37	  const [values, setValues] = useState(defaults);
38	  // Tell the owner once a save went through, e.g. so a card can show it is done.
39	  useEffect(() => { if (state.done) onDone?.(); }, [state.done]); // eslint-disable-line react-hooks/exhaustive-deps
40	  const [accountId, setAccountId] = useState(accounts?.[0]?.id ?? "");
41	  const open = openedAt !== null && Math.max(state.done ?? 0, removed.done ?? 0) < openedAt;
42	  const close = () => setOpenedAt(null);
43	  const currencyCode = accounts ? accounts.find(account => account.id === accountId)?.currencyCode ?? "" : defaults.currencyCode ?? "";
44	  const set = (key: keyof ScheduleDefaults) => (event: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => setValues(current => ({ ...current, [key]: event.target.value }));
45	  const summary = values.amount && values.startsOn ? `${cadenceWords[values.cadence] ?? ""}: ${values.amount} ${currencyCode} ${values.direction === "out" ? "going out" : "coming in"}, next on ${values.startsOn}` : "";
46	  const listId = `categories-${title.replace(/\W/g, "")}`;
47	  return <>
48	    <button type="button" className={triggerClassName} onClick={() => { setValues(defaults); setOpenedAt(Date.now()); }}>{trigger}</button>
49	    <Modal open={open} onClose={close} label={title} className="inset-0 size-full items-center justify-center px-4">
50	      <form action={submit} className="grid w-full max-w-md gap-3 rounded-xl border border-border bg-card p-5 shadow-xl">
51	        <Hidden values={{ ...hidden, shownStartsOn: defaults.startsOn, ...(currencyCode ? { currencyCode } : {}) }} />
52	        <h2 className="text-base font-semibold">{title}</h2>
53	        {summary && <p className="rounded-lg bg-muted px-3 py-2 text-sm">{summary}</p>}
54	        <label className="grid gap-1 text-sm">Name<input name="name" required maxLength={120} value={values.name} onChange={set("name")} className={inputClass} /></label>
55	        {accounts && <label className="grid gap-1 text-sm">Account<select name="accountId" required value={accountId} onChange={event => setAccountId(event.target.value)} className={inputClass}>
56	          {accounts.map(account => <option key={account.id} value={account.id}>{account.name} ({account.currencyCode})</option>)}</select></label>}
57	        <div className="grid grid-cols-2 gap-3">
58	          <label className="grid gap-1 text-sm">Direction<select name="direction" value={values.direction} onChange={set("direction")} className={inputClass}>
59	            <option value="out">Going out</option><option value="in">Coming in</option></select></label>
60	          <label className="grid gap-1 text-sm">Amount{currencyCode && ` (${currencyCode})`}<input name="amount" required inputMode="decimal" pattern="\d+([.,]\d+)?" value={values.amount} onChange={set("amount")} className={inputClass} /></label>
61	          <label className="grid gap-1 text-sm">How often<select name="scheduleCadence" value={values.cadence} onChange={set("cadence")} className={inputClass}>
62	            {recurringCadences.map(cadence => <option key={cadence} value={cadence}>{cadenceWords[cadence]}</option>)}</select></label>
63	          <label className="grid gap-1 text-sm">Next date<input name="startsOn" type="date" required value={values.startsOn} onChange={set("startsOn")} className={inputClass} /></label>
64	        </div>
65	        <label className="grid gap-1 text-sm">Category<input name="category" list={listId} maxLength={100} placeholder="e.g. Job, Rent, Subscriptions" value={values.category} onChange={set("category")} className={inputClass} /></label>
66	        <datalist id={listId}>{categories.map(name => <option key={name} value={name} />)}</datalist>
67	        {(state.error || removed.error) && <p role="alert" className="text-sm text-danger">{state.error ?? removed.error}</p>}
68	        <div className="flex flex-wrap items-center gap-2">
69	          <button disabled={pending || removing} className="min-h-10 rounded-lg bg-primary px-4 text-sm font-medium text-primary-foreground disabled:opacity-50">{pending ? "Saving…" : submitLabel}</button>
70	          <button type="button" onClick={close} className="min-h-10 rounded-lg border border-border px-4 text-sm hover:bg-muted">Cancel</button>
71	          {remove && <button formAction={removeSubmit} formNoValidate disabled={pending || removing} className="ml-auto min-h-10 rounded-lg px-3 text-sm text-danger hover:bg-muted disabled:opacity-50">{removing ? "Removing…" : "Remove from recurring"}</button>}
72	        </div>
73	      </form>
74	    </Modal>
75	  </>;
76	}
