17	async function loadLimitHistory(supabase: Db, workspaceId: string, from: string) {
18	  const rows: (MonthlyLimit & { plan_id: string })[] = [];
19	  for (let offset = 0; ; offset += 500) {
20	    const page = await supabase.from("spending_plan_limits").select("plan_id, limit_minor::text, enabled, version, effective_month").eq("workspace_id", workspaceId).lte("effective_month", from).order("effective_month").order("id").range(offset, offset + 499);
21	    if (page.error) throw page.error;
22	    rows.push(...page.data);
23	    if (page.data.length < 500) return rows;
24	  }
25	}
