27	async function loadSpending(supabase: Db, workspaceId: string, from: string, before: string) {
28	  type Row = { account_id: string; amount_minor: string; currency_code: string; status: string; kind: string; category_id: string | null; posted_on: string; refund_of_id: string | null; review_reasons: string[] };
29	  const coverageRows = await allPages<Row>((start, end, count) => supabase.from("effective_transactions")
30	    .select("account_id, amount_minor::text, currency_code, status, kind, category_id, posted_on, refund_of_id, review_reasons", count ? { count } : undefined)
31	    .eq("workspace_id", workspaceId).gte("posted_on", from).lt("posted_on", before).order("id").range(start, end), 1000);
32	  const rows: (SpendingPlanTransaction & { refundOfId: string | null })[] = coverageRows.map(item => ({ amountMinor: BigInt(item.amount_minor), currencyCode: item.currency_code, status: item.status, kind: item.kind, reviewReasons: item.review_reasons,
33	    categoryId: item.category_id, postedOn: String(item.posted_on).slice(0, 10), refundOfId: item.refund_of_id ?? null }));
34	  // Linked refunds count against the original purchase's category; batch the lookups in parallel.
35	  const refundIds = [...new Set(rows.flatMap(row => row.kind === "refund" && row.refundOfId ? [row.refundOfId] : []))];
36	  const batches = await Promise.all(Array.from({ length: Math.ceil(refundIds.length / 100) }, (_, index) =>
37	    supabase.from("transactions").select("id, category_id, currency_code").eq("workspace_id", workspaceId).in("id", refundIds.slice(index * 100, index * 100 + 100))));
38	  const originals = new Map<string, { category_id: string | null; currency_code: string }>();
39	  for (const { data, error } of batches) { if (error) throw error; for (const item of data ?? []) originals.set(item.id, item); }
40	  for (const row of rows) if (row.kind === "refund" && row.refundOfId) {
41	    const original = originals.get(row.refundOfId);
42	    row.refundOfCategoryId = original?.category_id ?? null;
43	    row.refundOfCurrencyCode = original?.currency_code ?? null;
44	  }
45	  return { rows, coverageRows };
46	}
