13	function GoalCard({ goal, allocations, accounts, locale, today }: { goal: Goal; allocations: Allocation[]; accounts: Account[]; locale?: string; today: string }) {
14	  const money = (amount: bigint | string) => formatMoney(amount, goal.currency_code, locale);
15	  const target = BigInt(goal.target_minor);
16	  const comparable = allocations.every(item => accounts.find(account => account.id === item.account_id)?.currency_code === goal.currency_code);
17	  const reserved = allocations.reduce((sum, item) => sum + BigInt(item.amount_minor), 0n);
18	  const saved = goal.recorded_saved_minor === null ? null : BigInt(goal.recorded_saved_minor);
19	  const monthly = BigInt(goal.planned_monthly_minor);
20	  const plan = goalContributionProjection({ targetMinor: target, savedMinor: saved, monthlyMinor: monthly, startsOn: goal.contribution_starts_on }, today);
21	  const late = !!(goal.target_date && plan.completionDate && plan.completionDate > goal.target_date);
22	  // The bar tracks recorded savings; reserved cash is a separate, virtual earmark.
23	  const progress = saved ?? (comparable ? reserved : null);
24	  const reservable = accounts.filter(account => allocations.some(item => item.account_id === account.id) || (goal.status === "active" && !account.archived_at && account.currency_code === goal.currency_code && liquid.includes(account.type)));
25	  return <article className="flex flex-col gap-3.5 rounded-2xl border border-border p-[18px]">
26	    <div className="flex flex-wrap items-baseline justify-between gap-2"><h3 className="text-[15px] font-medium">{goal.name}</h3>
27	      <span className="font-mono text-[11px] text-subtle">{goal.status === "active" ? `Priority ${goal.priority}` : goal.status.charAt(0).toUpperCase() + goal.status.slice(1)}</span></div>
28	    <div>
