8	type Projection = Pick<Awaited<ReturnType<typeof evaluatePlan>>, "forecast" | "available">;
9	type Scenario = { id: string; name: string; description: string | null; version: number };
10	
11	function figures(plan: Projection) {
12	  const last = plan.forecast.status === "available" ? plan.forecast.days.at(-1) : undefined;
13	  return {
14	    headroom: plan.available.status === "available" ? plan.available.amountMinor : null,
15	    tightest: plan.available.status === "available" ? plan.available.limitingDate : null,
16	    expected: last?.expectedMinor ?? null,
17	    conservative: last?.conservativeMinor ?? null,
18	  };
19	}
20	
21	function Comparison({ real, scenario, name, currency, locale, horizon }: { real: Projection; scenario: Projection; name: string; currency: string; locale?: string; horizon: number }) {
22	  const a = figures(real), b = figures(scenario);
23	  const money = (value: bigint | null) => value === null ? "Unavailable" : formatMoney(value, currency, locale);
24	  const delta = (x: bigint | null, y: bigint | null) => x === null || y === null ? "—" : `${y - x > 0n ? "+" : ""}${formatMoney(y - x, currency, locale)}`;
25	  const rows: [string, string, string, string][] = [
26	    ["Lowest headroom", money(a.headroom), money(b.headroom), delta(a.headroom, b.headroom)],
27	    ["Tightest day", a.tightest ?? "Unavailable", b.tightest ?? "Unavailable", ""],
28	    ["Expected at horizon", money(a.expected), money(b.expected), delta(a.expected, b.expected)],
29	    ["Conservative at horizon", money(a.conservative), money(b.conservative), delta(a.conservative, b.conservative)],
30	  ];
31	  return <div className="space-y-2">
32	    <div className="overflow-x-auto"><table className="w-full min-w-[28rem] text-sm"><caption className="sr-only">Real plan compared with {name}</caption>
33	      <thead><tr className="border-b border-border text-left text-xs text-muted-foreground"><th scope="col" className="py-2 font-medium" /><th scope="col" className="py-2 font-medium">Real plan</th><th scope="col" className="py-2 font-medium">{name}</th><th scope="col" className="py-2 font-medium">Difference</th></tr></thead>
34	      <tbody>{rows.map(([label, x, y, d]) => <tr key={label} className="border-b border-border last:border-0"><th scope="row" className="py-2 text-left font-medium">{label}</th><td className="py-2 font-mono">{x}</td><td className="py-2 font-mono">{y}</td><td className="py-2 font-mono">{d}</td></tr>)}</tbody>
35	    </table></div>
36	    <p className="text-sm">{a.headroom !== null && b.headroom !== null ? `Compared with the real plan: ${formatMoney(b.headroom - a.headroom, currency, locale)} change in spare cash over ${horizon} days.` : "Comparison unavailable until both forecasts have complete inputs."} Your real accounts are unchanged.</p>
37	  </div>;
38	}
