40	export function WhatIfSection({ scenarios, selected, href, real, scenario, accounts, currency, locale, today, horizon }: {
41	  scenarios: Scenario[]; selected?: Scenario; href: (id?: string) => string; real: Projection; scenario: Projection;
42	  accounts: { id: string; name: string }[]; currency: string; locale?: string; today: string; horizon: number;
43	}) {
44	  const tab = (active: boolean) => `inline-flex h-11 items-center rounded-[10px] border px-3.5 lg:h-[38px] text-[13px] font-medium ${active ? "border-foreground bg-foreground text-background" : "border-input text-muted-foreground hover:text-foreground"}`;
45	  return <section id="what-if" className={`${card} scroll-mt-24`} aria-labelledby="what-if-heading">
46	    <div><p className={eyebrow}>What if</p><h2 id="what-if-heading" className="mt-1 text-sm font-medium">What-if scenarios</h2><p className="mt-1 text-sm text-muted-foreground">Try a change side by side with your real plan. Nothing here touches real accounts.</p></div>
47	    <nav aria-label="Scenarios" className="flex flex-wrap gap-2"><Link href={href()} className={tab(!selected)}>Real plan</Link>{scenarios.map(item => <Link key={item.id} href={href(item.id)} className={tab(item.id === selected?.id)}>{item.name}</Link>)}</nav>
48	    {selected ? <>
49	      <Comparison real={real} scenario={scenario} name={selected.name} currency={currency} locale={locale} horizon={horizon} />
50	      <ScenarioEditor scenario={selected} />
51	      <form action={addScenarioEvent} className="flex flex-wrap gap-3 rounded-[14px] border border-dashed border-input p-4"><input type="hidden" name="scenarioId" value={selected.id} /><input name="name" required aria-label="Hypothetical event name" placeholder="Laptop, raise…" className={field} /><input name="amount" required inputMode="decimal" aria-label="Hypothetical change amount" placeholder="-1200.00" className={field} /><select name="accountId" aria-label="Account" className={field}>{accounts.map(account => <option key={account.id} value={account.id}>{account.name}</option>)}</select><select name="cadence" aria-label="Cadence" className={field}>{(["once", "monthly", "quarterly", "weekly", "biweekly", "yearly"] as const).map(value => <option key={value} value={value}>{cadenceLabels[value]}</option>)}</select><input type="date" name="startsOn" defaultValue={today} required aria-label="Start date" className={field} /><button className={button}>Add hypothetical change</button></form>
52	    </> : scenarios.length ? <p className="text-sm text-muted-foreground">Choose a scenario to compare it with the real plan.</p> : null}
53	    <form action={createScenario} className="flex flex-wrap gap-3"><input name="name" required maxLength={120} aria-label="New scenario name" placeholder="What if…" className={field} /><button className={button}>Create scenario</button></form>
54	  </section>;
55	}
