118	                <div className={`min-w-0 ${CARD_SIZES[size].span}`}>
119	                  <Suspense fallback={<CardSkeleton title={card.title} />}><HomeCard key={`${shown}-${size}`} card={card} context={context} version={shown} /></Suspense>
120	                </div>
121	                {filler > 0 && <div aria-hidden="true" className="hidden gap-3 lg:grid" style={{ gridColumn: `span ${filler}`, gridTemplateColumns: `repeat(${Math.max(1, Math.floor(filler / 2))}, minmax(0, 1fr))` }}>
122	                  {neighbours.slice(0, Math.max(1, Math.floor(filler / 2))).map(name => <div key={name} className="rounded-2xl border border-border bg-card p-5 opacity-40"><p className="text-sm font-medium">{name}</p></div>)}
123	                </div>}
124	              </div>
125	            </article>;
126	          })}
127	        </div>}
128	    </section>
129	  </main>;
130	}
