7	const FILTERS = { all: "All", attention: "Needs attention", imports: "Imports", analyses: "Analyses", chats: "Chats" } as const;
8	type Filter = keyof typeof FILTERS;
9	type Kind = "imports" | "analyses" | "chats";
10	type Item = { key: string; kind: Kind; at: string; badge: string; title: string; detail: string; href: string; attention: boolean; quiet?: boolean };
11	
12	const words = (value: string) => { const text = value.replaceAll("_", " "); return text[0].toUpperCase() + text.slice(1); };
13	const truncate = (value: string | null | undefined, max = 200) => !value ? "" : value.length > max ? `${value.slice(0, max)}…` : value;
14	
15	// One feed for Activity and Notifications. Each filter queries only the sources it shows.
16	export default async function ActivityPage({ searchParams }: { searchParams: Promise<{ filter?: string }> }) {
17	  let context: Awaited<ReturnType<typeof requireWorkspace>>;
18	  try { context = await requireWorkspace(); } catch { redirect("/login"); }
19	  const { supabase, workspace } = context;
20	  const requested = (await searchParams).filter;
21	  const filter: Filter = requested && requested in FILTERS ? requested as Filter : "all";
22	  const wants = (kind: Kind) => filter === "all" || filter === "attention" || filter === kind;
23	  const none = Promise.resolve({ data: null, error: null });
24	
25	  const [imports, jobs, saved, conversations, requests] = await Promise.all([
26	    wants("imports") ? supabase.from("imports").select("id, filename, status, total_rows, new_rows, matched_rows, review_rows, classification_review_rows, rejected_rows, error, created_at")
27	      .eq("workspace_id", workspace.id).neq("status", "undone").order("created_at", { ascending: false }).limit(20) : none,
28	    wants("analyses") ? supabase.from("background_jobs").select("id, status, stage, error, created_at, updated_at")
29	      .eq("workspace_id", workspace.id).eq("kind", "financial_review").order("created_at", { ascending: false }).limit(20) : none,
30	    wants("analyses") ? supabase.from("saved_analyses").select("job_id, title").eq("workspace_id", workspace.id).order("created_at", { ascending: false }).limit(20) : none,
31	    wants("chats") ? supabase.from("conversations").select("id, title, created_at").eq("workspace_id", workspace.id).order("created_at", { ascending: false }).limit(20) : none,
32	    wants("chats") ? supabase.from("chat_requests").select("id, conversation_id, status, error, usage, answer, updated_at").eq("workspace_id", workspace.id).order("created_at", { ascending: false }).limit(30) : none,
33	  ]);
34	  // A reply whose cards are still open needs attention, so cards from a chat that finished after the user left stay findable.
35	  const cards = new Map((requests.data ?? []).map(row => [row.id, row.status === "completed" ? answerCardIds(row.answer) : []]));
36	  const cardIds = [...new Set([...cards.values()].flat())];
37	  const open = await (cardIds.length ? supabase.from("agent_proposals").select("id").eq("workspace_id", workspace.id).in("id", cardIds).in("status", ["proposed", "failed"]) : none);
38	  const openIds = new Set((open.data ?? []).map(row => row.id as string));
39	  const waiting = (id: string) => (cards.get(id) ?? []).filter(card => openIds.has(card)).length;
40	  const errors = [imports, jobs, saved, conversations, requests, open].map(result => result.error).filter(Boolean);
41	  const titles = new Map((saved.data ?? []).map(row => [row.job_id, row.title]));
42	
43	  const items: Item[] = [
44	    ...(imports.data ?? []).map(row => {
45	      const review = row.review_rows + (row.classification_review_rows ?? 0);
46	      return { key: `import:${row.id}`, kind: "imports" as const, at: row.created_at, badge: "Import", title: `${row.filename} · ${row.status}`,
47	        detail: row.status === "failed" ? truncate(row.error) || "Failed" : `${row.new_rows} new · ${row.matched_rows} matched · ${row.review_rows} for review · ${row.rejected_rows} rejected · ${row.total_rows} total`,
48	        href: review > 0 ? `/import/${row.id}/review` : "/import", attention: row.status === "failed" || (row.status === "completed" && review > 0) };
49	    }),
50	    ...(jobs.data ?? []).map(row => ({ key: `analysis:${row.id}`, kind: "analyses" as const, at: row.updated_at ?? row.created_at, badge: "Analysis",
51	      title: titles.get(row.id) ?? "Deep Analysis", detail: row.status === "failed" ? truncate(row.error) || "Failed" : row.status === "completed" ? "Completed" : words(row.stage),
52	      href: `/ai/activity/${row.id}`, attention: row.status === "failed" })),
53	    ...(conversations.data ?? []).map(row => ({ key: `conversation:${row.id}`, kind: "chats" as const, at: row.created_at, badge: "Conversation", title: row.title,
54	      detail: "AI chat thread", href: `/ai?conversation=${row.id}`, attention: false })),
55	    // Successful replies are noise in the combined feed unless cards they raised are still waiting; the rest stay under Chats.
56	    ...(requests.data ?? []).map(row => ({ key: `chat:${row.id}`, kind: "chats" as const, at: row.updated_at, badge: "Chat",
57	      title: waiting(row.id) ? `Chat reply · ${waiting(row.id)} ${waiting(row.id) === 1 ? "card" : "cards"} waiting for you` : `Chat reply ${row.status}`,
58	      detail: [row.usage ? usageLabel(row.usage as ReportedUsage) : "", row.status === "failed" ? truncate(row.error) : ""].filter(Boolean).join(" · ") || words(row.status),
59	      href: `/ai?conversation=${row.conversation_id}`, attention: row.status === "failed" || waiting(row.id) > 0, quiet: row.status !== "failed" && !waiting(row.id) })),
60	  ];
61	  const visible = items.filter(item => filter === "attention" ? item.attention : filter === "all" ? !item.quiet : item.kind === filter)
62	    .sort((a, b) => b.at.localeCompare(a.at)).slice(0, 50);
63	  const day = (iso: string) => new Date(iso).toLocaleDateString(workspace.locale, { timeZone: workspace.timezone, dateStyle: "medium" });
64	  const groups = visible.reduce((map, item) => map.set(day(item.at), [...(map.get(day(item.at)) ?? []), item]), new Map<string, Item[]>());
65	
66	  return <main className="mx-auto w-full max-w-[1400px] space-y-6 px-4 py-6 sm:px-8 lg:py-8">
67	    <header className="flex flex-col gap-1">
68	      <p className="eyebrow">Imports · analyses · chats</p>
69	      <h1 className="page-title">Activity log</h1>
70	      <p className="mt-2 text-sm text-muted-foreground">Imports, analyses and chats in one feed. Failures and rows waiting for you are under Needs attention.</p>
71	    </header>
72	    <nav aria-label="Activity filters" className="flex flex-wrap gap-2">{Object.entries(FILTERS).map(([key, label]) =>
73	      <Link key={key} href={key === "all" ? "/ai/activity" : `/ai/activity?filter=${key}`} aria-current={filter === key ? "page" : undefined}
74	        className={`rounded-full border px-3 py-1.5 text-sm ${filter === key ? "border-brand bg-brand text-white" : "border-border bg-card hover:bg-muted"}`}>{label}</Link>)}</nav>
75	    {errors.length > 0 && <p role="alert" className="rounded-xl border border-border bg-card p-4 text-sm text-danger">Could not load part of this activity: {truncate(errors[0]?.message ?? "Unavailable")}</p>}
76	    {!errors.length && !visible.length && <p className="text-muted-foreground">{filter === "attention" ? "Nothing needs your attention." : <>No activity yet. <Link className="underline" href="/import">Import a statement</Link> or run a review from <Link className="underline" href="/ai">AI</Link>.</>}</p>}
77	    {[...groups].map(([label, entries]) => <section key={label} aria-label={label} className="space-y-2">
78	      <h2 className="eyebrow">{label}</h2>
79	      <ul className="divide-y divide-border overflow-hidden rounded-xl border border-border bg-card">{entries.map(item =>
80	        <li key={item.key}><Link href={item.href} className="flex items-start gap-3 px-5 py-4 hover:bg-muted/50">
81	          <span aria-hidden className={`mt-1.5 size-2 shrink-0 rounded-full ${item.attention ? "bg-warning" : "bg-border"}`} />
82	          <span className="min-w-0 flex-1">
83	            <span className="flex flex-wrap items-baseline justify-between gap-x-3"><span className="truncate font-medium">{item.title}</span>
84	              <span className="text-xs text-muted-foreground">{item.badge} · {new Date(item.at).toLocaleTimeString(workspace.locale, { timeZone: workspace.timezone, timeStyle: "short" })}</span></span>
85	            {item.detail && <span className="mt-0.5 block text-sm text-muted-foreground">{item.detail}</span>}
86	          </span>
87	        </Link></li>)}</ul>
88	    </section>)}
89	  </main>;
90	}
