1	"use client";
2	
3	import { useEffect, useRef, useState } from "react";
4	import { selectConversation } from "@/lib/ai/selected-conversation";
5	import { useChatRequest, type ChatAnswer, type ChatStreamEvent } from "@/lib/ai/use-chat-request";
6	import { useChatQueue } from "@/lib/ai/use-chat-queue";
7	import { useChatAttachments } from "@/lib/ai/use-chat-attachments";
8	import { ATTACHMENT_ONLY_MESSAGE, type ChatAttachment } from "@/lib/ai/chat-attachments";
9	import { ChatComposer, withSpoken } from "@/components/chat-composer";
10	import { VOICE_CONTEXT } from "@/lib/ai/voice-context";
11	import { ChatQueue } from "@/components/chat-queue";
12	import { DRAFT_EVENT } from "@/components/chat-messages";
13	
14	const suggestions = ["What changed in my spending last month?", "Where did most of my money go this month?", "Find my largest transactions", "Create a spending chart"];
15	
16	export type ChatFormEvents = {
17	  onStart?: (conversationId: string, question: string, attachments: ChatAttachment[], spoken: boolean) => void;
18	  onEvent?: (conversationId: string, event: ChatStreamEvent) => void;
19	  onDone?: (conversationId: string, question: string, result: ChatAnswer | null, attachments: ChatAttachment[]) => void;
20	};
21	
22	// The composer keeps its key when a new chat is first saved, so a draft typed during the answer stays put.
23	// autoSend sends one message as soon as the form mounts (a new artifact's first request).
24	export function ChatForm({ conversationId, selectionKey, empty = false, scope, placeholder = "Ask anything about your money", autoSend, onStart, onEvent, onDone }: { conversationId: string; selectionKey: string; isNewConversation?: boolean; empty?: boolean; scope?: React.ReactNode; placeholder?: string; autoSend?: string } & ChatFormEvents) {
25	  const [message, setMessage] = useState("");
26	  const chat = useChatRequest();
27	  const files = useChatAttachments();
28	  const { send, cancel, busy, error, status } = chat;
29	  useEffect(() => {
30	    const draft = (event: Event) => { const detail = (event as CustomEvent<{ prompt?: string; compact: boolean }>).detail; if (!detail.compact && detail.prompt) { setMessage(detail.prompt); document.getElementById("question")?.focus(); } };
31	    window.addEventListener(DRAFT_EVENT, draft);
32	    return () => window.removeEventListener(DRAFT_EVENT, draft);
33	  }, []);
34	
35	  function submit(event: React.FormEvent<HTMLFormElement>) {
36	    event.preventDefault();
37	    if (!message.trim() && !files.ready.length) return;
38	    // Files go with the next message the user sends themselves, never with a queued one.
39	    if (busy) { if (files.items.length) return; enqueue(message); setMessage(""); return; }
40	    void sendMessage(message, false, files.ready);
41	  }
42	
43	  // Spoken words go with what is typed and any ready files, queue like typed words while a reply runs, and wait in the box while files are unsettled.
44	  function sendSpoken(text: string) {
45	    const typed = withSpoken(message, text);
46	    if (files.uploading || files.items.some(item => item.error) || (busy && files.items.length)) { setMessage(typed); document.getElementById("question")?.focus(); return; }
47	    if (busy) { enqueue(typed); setMessage(""); return; }
48	    void sendMessage(typed, false, files.ready, true);
49	  }
50	
51	  async function sendMessage(typed: string, queued = false, attachments: ChatAttachment[] = [], spoken = false) {
52	    if (busy) return;
53	    const message = typed.trim() || ATTACHMENT_ONLY_MESSAGE;
54	    onStart?.(conversationId, message, attachments, spoken);
55	    if (!queued) { setMessage(""); files.clear(); }
56	    const result = await send({ conversationId, message, ...(spoken && { context: VOICE_CONTEXT }), ...(attachments.length && { attachments }) }, streamed => onEvent?.(conversationId, withSteers(streamed)));
57	    if (result) {
58	      selectConversation(selectionKey, conversationId);
59	    } else if (!queued) { setMessage(current => current || typed); files.restore(attachments); }
60	    onDone?.(conversationId, message, result, attachments);
61	  }
62	
63	  // A queued message that fails goes back to the queue, so the composer keeps what the user is typing.
64	  function startQueued(next: string) {
65	    if (busy) return false;
66	    void sendMessage(next, true);
67	    return true;
68	  }
69	  const { queue, enqueue, remove, steer, withSteers, canSteer } = useChatQueue(chat, conversationId, startQueued);
70	
71	  const autoSent = useRef<string | undefined>(undefined);
72	  useEffect(() => {
73	    if (!autoSend) { autoSent.current = undefined; return; }
74	    if (autoSent.current === autoSend) return;
75	    autoSent.current = autoSend;
76	    void sendMessage(autoSend);
77	  });
78	
79	  const composer = <><ChatQueue items={queue} canSteer={canSteer} onSteer={item => void steer(item)} onRemove={remove} /><ChatComposer id="question" label="Ask about your finances" value={message} onChange={setMessage} onSubmit={submit} onStop={() => void cancel()} busy={busy} placeholder={placeholder} busyText="Waiting for a response…" attachments={files} voice={{ onSend: sendSpoken }} /></>;
80	  const notices = <>{error && <p role="alert" className="mt-2 px-3 text-sm text-danger">{error}</p>}
81	    {status === "canceled" && <p role="status" className="mt-2 px-3 text-sm text-muted-foreground">Canceled. Previously completed edits remain in transaction history.</p>}</>;
82	
83	  if (empty) return <div className="flex flex-1 flex-col justify-center py-10">
84	    <h2 className="text-center font-display text-3xl font-semibold tracking-tight sm:text-4xl">How can I help with your money today?</h2>
85	    <div className="mt-8">{composer}{notices}</div>
86	    <div className="mt-4 flex flex-wrap justify-center gap-2">{suggestions.map(prompt => <button key={prompt} type="button" onClick={() => { setMessage(prompt); document.getElementById("question")?.focus(); }} className="rounded-full border border-border px-3.5 py-2 text-sm text-muted-foreground hover:bg-muted hover:text-foreground">{prompt}</button>)}</div>
87	    {scope}
88	  </div>;
89	
90	  return <div className="sticky bottom-0 mt-auto bg-gradient-to-t from-background from-70% to-transparent pt-6 pb-4">{composer}{notices}{scope}</div>;
91	}
