13	type Layout = { items: string[]; sizes: Record<string, CardSize> };
14	type Drag = { id: string; from: string[]; clone: HTMLElement; width: number; height: number; touch: boolean };
15	type Notice = { text: string; action?: { label: string; run: () => void } };
